// src/db/usersDB.js
import Dexie from "dexie";

export const usersDB = new Dexie("usersDatabase");

/*
  Version Notes:
  v1 → basic users table
  v2 → added:
      • dateCreated (ISO string)
      • createdBy (username who added the user)
      • lastLogin (ISO string)
      • loginCount (number)
*/
usersDB.version(1).stores({
  users: "++id, username, password, role, name, avatar"
});

// Upgrade schema: add analytics fields
usersDB.version(2).stores({
  users:
    "++id, username, password, role, name, avatar, dateCreated, createdBy, lastLogin, loginCount"
});

