// -------------------------------
// CRUD OPERATIONS
// -------------------------------

// Auto-append dateCreated and createdBy
export const addUser = async (user) => {
  const now = new Date().toISOString();
  const creator = localStorage.getItem("username") || "system";

  return await usersDB.users.add({
    ...user,
    dateCreated: now,
    createdBy: creator,
    lastLogin: null,
    loginCount: 0
  });
};

export const getAllUsers = async () => await usersDB.users.toArray();

export const deleteUser = async (id) => await usersDB.users.delete(id);

export const updateUser = async (id, data) =>
  await usersDB.users.update(id, data);

export const findUserByUsername = async (username) =>
  await usersDB.users.where("username").equals(username).first();

// -------------------------------
// Update avatar
// -------------------------------
export const updateUserAvatar = async (username, avatarData) => {
  const user = await findUserByUsername(username);
  if (user) {
    await usersDB.users.update(user.id, { avatar: avatarData });
  }
};

// -------------------------------
// Track login activity
// -------------------------------
export const recordUserLogin = async (username) => {
  const user = await findUserByUsername(username);
  if (user) {
    await usersDB.users.update(user.id, {
      lastLogin: new Date().toISOString(),
      loginCount: (user.loginCount || 0) + 1
    });
  }
};