import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  IconButton,
  List,
  ListItemButton,
  ListItemText,
  Divider,
  Tooltip,
} from "@mui/material";
import {
  People as PeopleIcon,
  Build as BuildIcon,
  Logout as LogoutIcon,
  Dashboard as DashboardIcon,
  HowToVote as HowToVoteIcon,
  AccountTree as AccountTreeIcon,
  BarChart as BarChartIcon,
  Settings as SettingsIcon,
  HelpOutline as HelpOutlineIcon,
  ChevronLeft as ChevronLeftIcon,
  ChevronRight as ChevronRightIcon,
} from "@mui/icons-material";
import { signOut } from "firebase/auth";
import { auth } from "../firebase";
import { useNavigate, useLocation } from "react-router-dom";

const Sidebar = () => {
  const [collapsed, setCollapsed] = useState(false);
  const [activeMenu, setActiveMenu] = useState("");
  const navigate = useNavigate();
  const location = useLocation();

  // ✅ Track active menu
  useEffect(() => {
    const path = location.pathname;
    if (path.includes("/admin/pcvl")) setActiveMenu("PCVL Management");
    else if (path.includes("/admin/voters")) setActiveMenu("Voters Profile Management");
    else if (path.includes("/admin/family-tree")) setActiveMenu("Family Tree Management");
    else if (path.includes("/admin/reports")) setActiveMenu("Reports");
    else if (path.includes("/admin/services")) setActiveMenu("Services");
    else setActiveMenu("Dashboard");
  }, [location.pathname]);


  // ✅ Logout
  const handleLogout = async () => {
    await signOut(auth);
    navigate("/login", { replace: true });
  };

  // ✅ Handle menu navigation
  const handleMenuClick = (menu) => {
    setActiveMenu(menu);
    switch (menu) {
      case "Dashboard":
        navigate("/admin");
        break;
      case "PCVL Management":
        navigate("/admin/pcvl");
        break;
      case "Voters Profile Management":
        navigate("/admin/voters");
        break;
      case "Family Tree Management":
        navigate("/admin/family-tree");
        break;
      case "Reports":
        navigate("/admin/reports");
        break;
      case "Services":
        navigate("/admin/services");
        break;
      default:
        break;
    }
  };

  // Professional menu structure with section headers
  const menuSections = [
    {
      header: null,
      items: [
        { name: "Dashboard", icon: <DashboardIcon sx={{ color: "#3f3f3fff" }} /> },
      ],
    },
    {
      header: "Management",
      items: [
        { name: "Voters Profile Management", icon: <HowToVoteIcon sx={{ color: "#3f3f3fff" }} /> },
        { name: "PCVL Management", icon: <PeopleIcon sx={{ color: "#3f3f3fff" }} /> },
        { name: "Family Tree", icon: <AccountTreeIcon sx={{ color: "#3f3f3fff" }} /> },
      ],
    },
    {
      header: "Analytics & Support",
      items: [
        { name: "Reports", icon: <BarChartIcon sx={{ color: "#3f3f3fff" }} /> },
        { name: "Services", icon: <BuildIcon sx={{ color: "#3f3f3fff" }} /> },
      ],
    },
  ];

  return (
    <Box
      sx={{
        width: { xs: collapsed ? 56 : 200, md: collapsed ? 64 : 220 },
        bgcolor: "#f8f9fa",
        color: "#111318",
        display: "flex",
        flexDirection: "column",
        transition: "width 0.3s cubic-bezier(.4,2,.6,1)",
        minHeight: "100vh",
        borderRight: "1.5px solid #e5e7eb",
        boxShadow: collapsed ? "0 2px 8px rgba(31,94,236,0.08)" : "0 8px 32px rgba(31,94,236,0.10)",
        overflow: "hidden",
        zIndex: 1200,
        position: "relative",
      }}
    >
      {/* Brand/Header */}
      {/* Toggle button at top right corner */}
      <Box sx={{ position: "relative", width: "100%" }}>
        <IconButton
          onClick={() => setCollapsed((prev) => !prev)}
          sx={{
            position: "absolute",
            top: 300,
            right: -10,
            color: "#135bec",
            borderRadius: 2,
            p: 0.5,
            bgcolor: collapsed ? "#e3eaff" : "transparent",
            '&:hover': { bgcolor: "#e3eaff" },
            boxShadow: collapsed ? "0 1px 4px #e3eaff" : undefined,
            transition: "background 0.2s, color 0.2s, margin-left 0.2s",
            zIndex: 20,
            ml: collapsed ? '28px' : 0,
          }}
          size="small"
          aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
        >
          {collapsed ? <ChevronRightIcon fontSize="small" /> : <ChevronLeftIcon fontSize="small" />}
        </IconButton>
        <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center", pt: 2, pb: 0.5 }}>
          <Box
            sx={{
              bgcolor: "#135bec1A",
              color: "#135bec",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              borderRadius: 2,
              width: 32,
              height: 32,
              fontSize: 20,
              fontWeight: 700,
              mb: 0.5,
              transition: "all 0.3s",
            }}
          >
            <HowToVoteIcon fontSize="small" />
          </Box>
          {!collapsed && (
            <Box sx={{ textAlign: "center", width: "100%" }}>
              <Typography variant="subtitle1" sx={{ fontWeight: 700, color: "#135bec", letterSpacing: 0.5, fontSize: 16, lineHeight: 1.1 }}>
                VoterAdmin
              </Typography>
              <Typography variant="caption" sx={{ color: "#6b7280", fontWeight: 500, fontSize: 11 }}>
                System Manager
              </Typography>
            </Box>
          )}
        </Box>
      </Box>
      <Divider sx={{ borderColor: "#e5e7eb", mt: 0.5 }} />

      {/* User Info removed, now in Topbar */}
      <Divider sx={{ borderColor: "#e5e7eb", mb: 1 }} />

      {/* Menu Sections */}
      <Box sx={{ flexGrow: 1, overflowY: "auto", px: 0.5 }}>
        {menuSections.map((section, idx) => (
          <Box key={idx} sx={{ mb: 0.2 }}>
            {section.header && !collapsed && (
              <Typography
                variant="caption"
                sx={{
                  color: "#8b8d8f",
                  fontWeight: 700,
                  textTransform: "uppercase",
                  letterSpacing: 0.5,
                  pl: 1,
                  pb: 0.2,
                  pt: idx === 0 ? 0 : 0.7,
                  fontSize: 10,
                }}
              >
                {section.header}
              </Typography>
            )}
            <List sx={{ py: 0 }}>
              {section.items.map((item) => (
                <Tooltip key={item.name} title={collapsed ? item.name : ""} placement="right" arrow>
                  <ListItemButton
                    onClick={() => handleMenuClick(item.name)}
                    selected={activeMenu === item.name}
                    sx={{
                      borderRadius: 1.5,
                      my: 0.1,
                      mx: 0.2,
                      color: activeMenu === item.name ? "#135bec" : "#22292f",
                      bgcolor:
                        activeMenu === item.name ? "#e3eaff" : "transparent",
                      fontWeight: activeMenu === item.name ? 700 : 500,
                      '&:hover': { bgcolor: "#f0f6ff" },
                      justifyContent: collapsed ? "center" : "flex-start",
                      transition: "all 0.18s cubic-bezier(.4,2,.6,1)",
                      minHeight: 32,
                      px: collapsed ? 0.5 : 1.2,
                    }}
                  >
                    <Box sx={{ mr: collapsed ? 0 : 1, display: "flex", alignItems: "center" }}>{React.cloneElement(item.icon, { fontSize: "small" })}</Box>
                    {!collapsed && (
                      <ListItemText
                        primary={item.name}
                        primaryTypographyProps={{
                          color: activeMenu === item.name ? "#135bec" : "#22292f",
                          fontWeight: activeMenu === item.name ? 800 : 600,
                          fontSize: 14,
                          letterSpacing: 0.1,
                        }}
                      />
                    )}
                  </ListItemButton>
                </Tooltip>
              ))}
            </List>
          </Box>
        ))}
      </Box>

      {/* Settings & Logout */}
      <Box sx={{ p: 1, borderTop: "1.5px solid #e5e7eb", bgcolor: "#f8f9fa" }}>
        <Box sx={{ display: "flex", flexDirection: "column", gap: 0.5 }}>
          <Tooltip title={collapsed ? "Settings" : ""} placement="right" arrow>
            <ListItemButton
              onClick={() => navigate("/admin/settings")}
              sx={{
                borderRadius: 1.5,
                justifyContent: collapsed ? "center" : "flex-start",
                color: "#22292f",
                '&:hover': { bgcolor: "#f0f6ff" },
                mb: 0.2,
                minHeight: 32,
                px: collapsed ? 0.5 : 1.2,
              }}
            >
              <SettingsIcon sx={{ mr: collapsed ? 0 : 1, color: "#135bec" }} fontSize="small" />
              {!collapsed && (
                <ListItemText
                  primary="Settings"
                  primaryTypographyProps={{ color: "#22292f", fontWeight: 600, fontSize: 13 }}
                />
              )}
            </ListItemButton>
          </Tooltip>
          <Tooltip title={collapsed ? "Help" : ""} placement="right" arrow>
            <ListItemButton
              onClick={() => navigate("/admin/help")}
              sx={{
                borderRadius: 1.5,
                justifyContent: collapsed ? "center" : "flex-start",
                color: "#22292f",
                '&:hover': { bgcolor: "#f0f6ff" },
                mb: 0.2,
                minHeight: 32,
                px: collapsed ? 0.5 : 1.2,
              }}
            >
              <HelpOutlineIcon sx={{ mr: collapsed ? 0 : 1, color: "#135bec" }} fontSize="small" />
              {!collapsed && (
                <ListItemText
                  primary="Help"
                  primaryTypographyProps={{ color: "#22292f", fontWeight: 600, fontSize: 13 }}
                />
              )}
            </ListItemButton>
          </Tooltip>
          <Tooltip title={collapsed ? "Logout" : ""} placement="right" arrow>
            <ListItemButton
              onClick={handleLogout}
              sx={{
                borderRadius: 1.5,
                justifyContent: collapsed ? "center" : "flex-start",
                color: "#e53935",
                '&:hover': { bgcolor: "#ffeaea" },
                minHeight: 32,
                px: collapsed ? 0.5 : 1.2,
              }}
            >
              <LogoutIcon sx={{ mr: collapsed ? 0 : 1, color: "#e53935" }} fontSize="small" />
              {!collapsed && (
                <ListItemText
                  primary="Logout"
                  primaryTypographyProps={{ color: "#e53935", fontWeight: 700, fontSize: 13 }}
                />
              )}
            </ListItemButton>
          </Tooltip>
        </Box>
      </Box>
    </Box>
  );
};

export default Sidebar;