// src/pages/encoder/dialogs/PayoutTaskDialog.jsx
import React, { useState } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Divider,
  Stack,
  CircularProgress,
} from "@mui/material";
import RestartAltIcon from "@mui/icons-material/RestartAlt";

const PayoutTaskDialog = ({ open, onClose, rowData, onRegister, onReset, encoder }) => {
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [confirmAction, setConfirmAction] = useState(""); // "cancel" or "reset"
  const [registerLoading, setRegisterLoading] = useState(false);
  const [resetLoading, setResetLoading] = useState(false);

  if (!rowData) return null;

  const isAlreadyRegistered = rowData.STATUS === "Registered";
  const isRegisteredByMe = rowData.Encoder === encoder;

  const entries = [...Object.entries(rowData)];
  if (!rowData.Encoder) {
    entries.push(["Encoder", encoder ?? "—"]);
  }

  // Cancel button opens confirmation
  const handleCancelClick = () => {
    setConfirmAction("cancel");
    setConfirmOpen(true);
  };

  // Reset button opens confirmation
  const handleResetClick = () => {
    setConfirmAction("reset");
    setConfirmOpen(true);
  };

  const handleConfirm = async () => {
    setConfirmOpen(false);
    if (confirmAction === "cancel") {
      onClose();
    } else if (confirmAction === "reset") {
      setResetLoading(true);
      try {
        await onReset(rowData);
      } finally {
        setResetLoading(false);
      }
    }
  };

  const handleRegisterClick = async () => {
    setRegisterLoading(true);
    try {
      await onRegister(rowData);
    } finally {
      setRegisterLoading(false);
    }
  };

  return (
    <>
      {/* Main Beneficiary Dialog */}
      <Dialog
        open={open}
        onClose={() => {}}
        disableEscapeKeyDown
        fullWidth
        maxWidth="sm"
        PaperProps={{ sx: { borderRadius: 3, p: 2 } }}
      >
        <DialogTitle sx={{ fontWeight: 700, textAlign: "center", mb: 1 }}>
          Beneficiary Details
        </DialogTitle>

        <Divider sx={{ mb: 1 }} />

        <DialogContent>
          <Stack spacing={1}>
            {entries.map(([key, value], i) => {
              const isStatus = key.toUpperCase() === "STATUS";
              const isRegistered = value === "Registered";

              return (
                <Stack
                  key={i}
                  spacing={0.25}
                  sx={
                    isStatus && isRegistered
                      ? {
                          bgcolor: isRegisteredByMe ? "success.100" : "grey.100",
                          borderRadius: 1,
                          p: 0.5,
                        }
                      : {}
                  }
                >
                  <Typography
                    variant="caption"
                    color="text.secondary"
                    sx={{ fontWeight: 600 }}
                  >
                    {key}
                  </Typography>
                  <Typography
                    variant="body2"
                    sx={{
                      fontWeight: 600,
                      lineHeight: 1.3,
                      color:
                        isStatus && isRegistered
                          ? isRegisteredByMe
                            ? "success.main"
                            : "text.secondary"
                          : "text.primary",
                    }}
                  >
                    {value ?? "—"}
                  </Typography>
                  {i < entries.length - 1 && <Divider sx={{ mt: 0.5 }} />}
                </Stack>
              );
            })}
          </Stack>
        </DialogContent>

        <Divider sx={{ mt: 1 }} />

        <DialogActions sx={{ pt: 1, justifyContent: "space-between" }}>
          <Stack direction="row" spacing={1}>
            <Button
              onClick={handleCancelClick}
              variant="outlined"
              color="error"
              sx={{ borderRadius: 2 }}
              disabled={registerLoading || resetLoading}
            >
              Cancel
            </Button>

            {isAlreadyRegistered && (
              <Button
                startIcon={resetLoading ? <CircularProgress size={18} color="inherit" /> : <RestartAltIcon />}
                onClick={handleResetClick}
                variant="outlined"
                color="warning"
                sx={{ borderRadius: 2 }}
                disabled={registerLoading || resetLoading}
              >
                {resetLoading ? "Resetting..." : "Reset"}
              </Button>
            )}
          </Stack>

          <Button
            onClick={handleRegisterClick}
            variant="contained"
            color="primary"
            sx={{ borderRadius: 2 }}
            disabled={isAlreadyRegistered || registerLoading || resetLoading}
            startIcon={registerLoading && <CircularProgress size={18} color="inherit" />}
          >
            {registerLoading
              ? "Registering..."
              : isAlreadyRegistered
              ? isRegisteredByMe
                ? "Registered by You"
                : "Registered"
              : "Register"}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Confirmation Dialog for Cancel and Reset */}
      <Dialog
        open={confirmOpen}
        onClose={() => {}}
        disableEscapeKeyDown
        PaperProps={{ sx: { borderRadius: 3, p: 2 } }}
      >
        <DialogTitle sx={{ fontWeight: 700, textAlign: "center" }}>
          Confirm {confirmAction === "cancel" ? "Cancel" : "Reset"}
        </DialogTitle>
        <Divider sx={{ mb: 2 }} />
        <DialogContent>
          <Typography textAlign="center">
            {confirmAction === "cancel"
              ? "Are you sure you want to cancel?"
              : "Are you sure you want to reset this registered row?"}
          </Typography>
        </DialogContent>
        <DialogActions sx={{ justifyContent: "center", pt: 2 }}>
          <Button
            onClick={() => setConfirmOpen(false)}
            variant="outlined"
            color="error"
            sx={{ borderRadius: 2 }}
            disabled={registerLoading || resetLoading}
          >
            No
          </Button>
          <Button
            onClick={handleConfirm}
            variant="contained"
            color="primary"
            sx={{ borderRadius: 2 }}
            disabled={registerLoading || resetLoading}
            startIcon={resetLoading && <CircularProgress size={18} color="inherit" />}
          >
            Yes
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default PayoutTaskDialog;