import React, { useEffect, useState } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Typography,
  Button,
  List,
  ListItem,
  ListItemText,
  Box,
  Badge,
  Divider,
  CircularProgress,
} from "@mui/material";
import NotificationsIcon from "@mui/icons-material/Notifications";
import { db } from "../../firebase";
import { collection, query, orderBy, limit, onSnapshot } from "firebase/firestore";

const NotificationDialog = ({ open, onClose }) => {
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!open) return;
    const q = query(collection(db, "notifications"), orderBy("timestamp", "desc"), limit(20));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const notifs = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setNotifications(notifs);
      setLoading(false);
    });
    return () => unsubscribe();
  }, [open]);

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle sx={{ display: "flex", alignItems: "center", gap: 1 }}>
        <Badge color="error" badgeContent={notifications.length}>
          <NotificationsIcon color="primary" />
        </Badge>
        Notifications
      </DialogTitle>
      <Divider />
      <DialogContent>
        {loading ? (
          <Box sx={{ display: "flex", justifyContent: "center", py: 3 }}>
            <CircularProgress size={32} />
          </Box>
        ) : notifications.length === 0 ? (
          <Typography variant="body2" color="text.secondary" align="center">
            No notifications found.
          </Typography>
        ) : (
          <List>
            {notifications.map((notif) => (
              <ListItem key={notif.id} alignItems="flex-start" sx={{ mb: 1 }}>
                <ListItemText
                  primary={notif.title || "Notification"}
                  secondary={
                    <>
                      <Typography variant="body2" color="text.secondary">
                        {notif.message || "No details provided."}
                      </Typography>
                      {notif.timestamp && (
                        <Typography variant="caption" color="text.disabled">
                          {new Date(notif.timestamp.seconds * 1000).toLocaleString()}
                        </Typography>
                      )}
                    </>
                  }
                />
              </ListItem>
            ))}
          </List>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} variant="contained" color="primary">
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default NotificationDialog;
