import React, { useState, useEffect } from "react";
import { auth, db } from "../firebase";
import { doc, getDoc } from "firebase/firestore";
import {
  AppBar,
  Toolbar,
  Box,
  Typography,
  IconButton,
  InputBase,
  Badge,
  Divider,
  Avatar,
  Paper,
} from "@mui/material";
import {
  Search as SearchIcon,
  Notifications as NotificationsIcon,
  HelpOutline as HelpOutlineIcon,
} from "@mui/icons-material";
import NotificationDialog from "./dialogs/NotificationDialog";
import HelpDialog from "./dialogs/HelpDialog";

const Topbar = () => {
      const [notifOpen, setNotifOpen] = useState(false);
    const [helpOpen, setHelpOpen] = useState(false);
  const [userData, setUserData] = useState(null);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (user) => {
      if (!user) {
        setUserData(null);
        return;
      }
      try {
        const snap = await getDoc(doc(db, "users", user.uid));
        const data = snap.exists() ? snap.data() : {};
        setUserData({
          name: data.name || user.displayName || user.email,
          role: (data.role || "Encoder").toUpperCase(),
        });
      } catch (err) {
        setUserData(null);
      }
    });
    return () => unsubscribe();
  }, []);

  return (
    <AppBar position="static" elevation={0} sx={{ bgcolor: "#fff", color: "#222", borderBottom: "1.5px solid #e5e7eb" }}>
      <Toolbar sx={{ minHeight: 64, px: 3, display: "flex", justifyContent: "space-between" }}>
        {/* Search Box */}
        <Paper
          component="form"
          sx={{
            p: "2px 8px",
            display: "flex",
            alignItems: "center",
            width: 260,
            bgcolor: "#f8f9fa",
            boxShadow: "none",
            borderRadius: 2,
            border: "1px solid #e5e7eb",
          }}
        >
          <SearchIcon sx={{ color: "#888", mr: 1 }} />
          <InputBase
            sx={{ ml: 1, flex: 1, fontSize: 15 }}
            placeholder="Search voters, ID, or records..."
            inputProps={{ 'aria-label': 'search voters' }}
          />
        </Paper>

        {/* Right Side */}
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          {/* Notification */}
          <IconButton sx={{ color: "#555" }} onClick={() => setNotifOpen(true)}>
            <Badge color="error">
              <NotificationsIcon />
            </Badge>
          </IconButton>
          <NotificationDialog open={notifOpen} onClose={() => setNotifOpen(false)} />
          {/* Help */}
          <IconButton sx={{ color: "#555" }} onClick={() => setHelpOpen(true)}>
            <HelpOutlineIcon />
          </IconButton>
          <HelpDialog open={helpOpen} onClose={() => setHelpOpen(false)} />
          {/* Divider */}
          <Divider orientation="vertical" flexItem sx={{ mx: 2, bgcolor: "#e5e7eb", height: 32 }} />
          {/* Admin User Info */}
          <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
            <Box sx={{ textAlign: "right", mr: 1 }}>
              <Typography variant="subtitle2" sx={{ fontWeight: 700, color: "#222", lineHeight: 1 }}>
                {userData?.name || "Admin User"}
              </Typography>
              <Typography variant="caption" sx={{ color: "#888", fontWeight: 500, fontSize: 12 }}>
                {userData?.role || "Super Admin"}
              </Typography>
            </Box>
            <Avatar sx={{ width: 36, height: 36, bgcolor: "#135bec", color: "#fff", fontWeight: 700 }}>
              {userData?.name ? userData.name.charAt(0).toUpperCase() : "A"}
            </Avatar>
          </Box>
        </Box>
      </Toolbar>
    </AppBar>
  );
};

export default Topbar;
