import React, { useState, useEffect } from "react";
import Sidebar from "../../components/Sidebar";
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  LinearProgress,
  TablePagination,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Slide,
} from "@mui/material";
import { Search, Close, Edit, SwapHoriz, Save, PersonSearch} from "@mui/icons-material";
import { db } from "../../firebase";
import {
  collection,
  query,
  orderBy,
  limit,
  getDocs,
  where,
  startAfter,
} from "firebase/firestore";

// Debounce hook
function useDebounce(value, delay) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return debounced;
}

const AdminVotersProfileMgt = () => {
  // Fixed professional headers for the voters table
  const headers = [
    "Voters Name",
    "Voters Address",
    "Voters Barangay",
    "Profile Barangay",
    "Profile Purok",
    "Precinct",
    "Political Status",
    "Family Type",
  ];
  const [voters, setVoters] = useState([]);
  const [search, setSearch] = useState("");
  const debouncedSearch = useDebounce(search, 300);
  const [loading, setLoading] = useState(false);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [page, setPage] = useState(0);
  const [pageCursors, setPageCursors] = useState([]); // Array of lastDoc for each page
  const [editingMember, setEditingMember] = useState(null);
  const [serverTime, setServerTime] = useState(new Date());
  const [selectedVoter, setSelectedVoter] = useState(null);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [confirmAction, setConfirmAction] = useState(null);
  const [confirmMessage, setConfirmMessage] = useState("");


  // Update server time every second
  useEffect(() => {
    const timer = setInterval(() => setServerTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Load voters from Firestore with pagination and search
  useEffect(() => {
    const fetchVoters = async () => {
      setLoading(true);
      try {
        let votersQuery = collection(db, "voters");
        let q = query(votersQuery, orderBy("Voters Name"), limit(rowsPerPage));
        if (debouncedSearch) {
          q = query(
            votersQuery,
            where("Voters Name", ">=", debouncedSearch),
            where("Voters Name", "<=", debouncedSearch + "\uf8ff"),
            orderBy("Voters Name"),
            limit(rowsPerPage)
          );
        }
        // Only use startAfter for next/prev navigation
        let startDoc = null;
        if (page > 0 && pageCursors.length >= page) {
          startDoc = pageCursors[page - 1];
        }
        if (startDoc) {
          q = query(q, startAfter(startDoc));
        }
        const snapshot = await getDocs(q);
        const data = snapshot.docs.map((doc) => doc.data());
        setVoters(data);
        if (data.length > 0) {
          // Store the lastDoc for this page for next navigation
          const newCursors = [...pageCursors];
          newCursors[page] = snapshot.docs[snapshot.docs.length - 1];
          setPageCursors(newCursors);
        }
      } catch (err) {
        console.error("Error loading voters from Firestore:", err);
        setVoters([]);
      } finally {
        setLoading(false);
      }
    };
    fetchVoters();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [debouncedSearch, rowsPerPage, page]);

  // Data is already paginated from Firestore
  const paginatedVoters = voters;

  const handleChangePage = (_, newPage) => {
    setPage(newPage);
  };
  const handleChangeRowsPerPage = (e) => {
    setRowsPerPage(parseInt(e.target.value, 10));
    setPage(0);
    setPageCursors([]);
  };

  // Open confirmation dialog
  const openConfirm = (message, action) => {
    setConfirmMessage(message);
    setConfirmAction(() => action);
    setConfirmOpen(true);
  };

  return (
    <Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#f0f2f5" }}>
      <Sidebar />

      <Box
  sx={{
    flexGrow: 1,
    p: 4,
    position: "relative",
    overflowX: "auto",
    width: { xs: "100%", md: "calc(100% - 260px)" },
  }}
>
  {/* Header with Server Time */}
 <Box
  sx={{
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    mb: 3,
  }}
>
  <Typography
    variant="h4"
    sx={{
      color: "#1f8ef1",
      fontWeight: 600,
      display: "flex",
      alignItems: "center",
      gap: 1,
    }}
  >
    <PersonSearch fontSize="large" />
    Voters Profile Management
  </Typography>

  {/* Server time as inline tag */}
  <Typography
    variant="subtitle2"
    sx={{
      bgcolor: "#8b8d8f33",
      color: "#14141480",
      fontWeight: 600,
      px: 1.5,
      py: 1,
      borderRadius: 1,
      fontSize: 20,
    }}
  >
    {serverTime.toLocaleString("en-US", {
      hour12: false,
      month: "short",
      day: "2-digit",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    })}
  </Typography>
</Box>

        <TextField
          fullWidth
          variant="outlined"
          size="small"
          placeholder="Search family head or member..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(0);
            setPageCursors([]);
          }}
          InputProps={{ startAdornment: <Search sx={{ mr: 1, color: "gray" }} /> }}
          sx={{ mb: 2 }}
        />

       {loading && (
        <Box sx={{ position: "relative", mb: 2 }}>
          <LinearProgress sx={{ height: 10, borderRadius: 5 }} />
          <Typography
            variant="caption"
            sx={{
              position: "absolute",
              top: 0,
              left: "50%",
              transform: "translateX(-50%)",
              color: "#000",
              fontWeight: 600,
            }}
          >
            Loading...
          </Typography>
        </Box>
      )}

        <Paper sx={{ bgcolor: "#fff", borderRadius: 2, boxShadow: "0 4px 20px rgba(31,142,241,0.1)" }}>
        <Box
    sx={{
      transition: "opacity 0.4s ease",
      opacity: loading ? 0.5 : 1,
    }}
  >
  <TableContainer
  sx={{
    maxHeight: 400,
    borderRadius: 2,
    boxShadow: "0 2px 10px rgba(0,0,0,0.05)",
    "& .MuiTableRow-hover:hover": {
      backgroundColor: "#e3f2fd !important",
    },
    "&::-webkit-scrollbar": { width: 0, background: "transparent" },
  }}
>
  <Table stickyHeader>
    <TableHead>
      <TableRow>
        {headers.map((header, i) => (
          <TableCell
            key={i}
            sx={{
              color: "#fff",
              fontWeight: 600,
              backgroundColor: "#252424f5",
              position: "sticky",
              top: 0,
              zIndex: 1,
              fontSize: 12,
              py: 0.5,
              px: 1,
              whiteSpace: "nowrap",
              minWidth: 120,
              maxWidth: 180,
            }}
          >
            {header}
          </TableCell>
        ))}
      </TableRow>
    </TableHead>

   <TableBody>
  {paginatedVoters.length === 0 ? (
    <TableRow>
      <TableCell align="center" colSpan={headers.length}>
        No voter data — import or check Excel file.
      </TableCell>
    </TableRow>
  ) : (
    paginatedVoters.map((voter, index) => (
      <TableRow
        key={index}
        hover
        sx={{ cursor: "pointer" }}
        onClick={() => setSelectedVoter(voter)}
      >
        {headers.map((header, i) => (
          <TableCell key={i} sx={{ fontSize: 13, py: 0.5, px: 1, whiteSpace: "nowrap", maxWidth: 180, overflow: "hidden", textOverflow: "ellipsis" }}>
            {voter[header] || "-"}
          </TableCell>
        ))}
      </TableRow>
    ))
  )}
</TableBody>
  </Table>
</TableContainer>
  <TablePagination
    component="div"
    count={-1}
    page={page}
    onPageChange={handleChangePage}
    rowsPerPage={rowsPerPage}
    onRowsPerPageChange={handleChangeRowsPerPage}
    rowsPerPageOptions={[5, 10, 20, 50, 100]}
    labelDisplayedRows={() => `Page ${page + 1}`}
  />
  </Box>
</Paper>

{/* Voter Profile Dialog */}
<Dialog
  open={Boolean(selectedVoter)}
  onClose={() => setSelectedVoter(null)}
  fullWidth
  maxWidth="md"
  TransitionComponent={Slide}
  TransitionProps={{ direction: "up" }}
  sx={{ "& .MuiDialog-paper": { width: "95%", maxWidth: 900 } }}
>
  <DialogTitle
    sx={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      bgcolor: "#252424f5",
      color: "#fff",
    }}
  >
    <Typography
      variant="h6"
      sx={{ fontSize: 18, display: "flex", alignItems: "center", gap: 1 }}
    >
      Voter Profile — {selectedVoter?.["Voters Name"] || "-"}
    </Typography>
    <IconButton onClick={() => setSelectedVoter(null)} sx={{ color: "#fff" }}>
    </IconButton>
  </DialogTitle>

  <DialogContent dividers sx={{ p: 2 }}>
    {selectedVoter ? (
      <TableContainer component={Paper} sx={{ maxHeight: 400 }}>
        <Table stickyHeader size="small">
          <TableHead>
            <TableRow>
              {headers.map((header, i) => (
                <TableCell
                  key={i}
                  sx={{
                    bgcolor: "#252424f5",
                    color: "#fff",
                    fontWeight: 600,
                    fontSize: 12,
                    py: 0.5,
                    px: 1,
                    whiteSpace: "nowrap",
                    position: "sticky",
                    top: 0,
                    zIndex: 1,
                    minWidth: 120,
                    maxWidth: 180,
                  }}
                >
                  {header}
                </TableCell>
              ))}
            </TableRow>
          </TableHead>
          <TableBody>
            <TableRow>
              {headers.map((header, i) => (
                <TableCell key={i} sx={{ fontSize: 13, py: 0.5, px: 1, whiteSpace: "nowrap", maxWidth: 180, overflow: "hidden", textOverflow: "ellipsis" }}>
                  {selectedVoter[header] || "-"}
                </TableCell>
              ))}
            </TableRow>
          </TableBody>
        </Table>
      </TableContainer>
    ) : (
      <Typography
        variant="body2"
        sx={{ textAlign: "center", py: 2, fontStyle: "italic", color: "#777" }}
      >
        No voter data available.
      </Typography>
    )}
  </DialogContent>

  <DialogActions sx={{ px: 3, py: 2 }}>
    <Button
  variant="outlined"
  startIcon={<Edit />}
  color="primary"
  onClick={() =>
    openConfirm(
      "Do you want to edit this voter’s details?",
      () => setEditingMember({ ...selectedVoter })
    )
  }
  sx={{ borderRadius: 2 }}
>
  Edit Details
</Button>
    <Button
      variant="outlined"
      startIcon={<SwapHoriz />}
      color="secondary"
      onClick={() =>
        openConfirm(
          `Transfer "${selectedVoter["Family Members"]}" to another family?`,
          () => {
            alert(`Voter ${selectedVoter["Family Members"]} transferred!`);
          }
        )
      }
      sx={{ borderRadius: 2 }}
    >
      Transfer Family
    </Button>

    <Button
      variant="contained"
      color="error"
      startIcon={<Close />}
      onClick={() => setSelectedVoter(null)}
      sx={{ borderRadius: 2 }}
    >
      Close
    </Button>
  </DialogActions>
</Dialog>
            {/* Edit Member Dialog */}
      <Dialog
        open={Boolean(editingMember)}
        onClose={() => setEditingMember(null)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <Edit fontSize="small" color="primary" />
          Edit Member Details
        </DialogTitle>

        <DialogContent dividers>
          {editingMember &&
            headers.map((header) => (
              <TextField
                key={header}
                label={header}
                value={editingMember[header] || ""}
                onChange={(e) =>
                  setEditingMember((prev) => ({ ...prev, [header]: e.target.value }))
                }
                fullWidth
                sx={{ mb: 2 }}
              />
            ))}
        </DialogContent>

        <DialogActions sx={{ justifyContent: "space-between", px: 2, pb: 2 }}>
          <Button
            variant="outlined"
            startIcon={<Close />}
            color="secondary"
            onClick={() => setEditingMember(null)}
            sx={{ borderRadius: 2 }}
          >
            Cancel
          </Button>
          <Button
            variant="outlined"
            startIcon={<Save />}
            color="primary"
            onClick={() => {
              setVoters((prev) =>
                prev.map((v) =>
                  v["Voters Name"] === editingMember["Voters Name"]
                    ? { ...editingMember }
                    : v
                )
              );
              setEditingMember(null);
            }}
            sx={{ borderRadius: 2 }}
          >
            Save
          </Button>
        </DialogActions>
      </Dialog>

        {/* Confirmation Dialog */}
        <Dialog open={confirmOpen} onClose={() => setConfirmOpen(false)}>
          <DialogTitle>Confirm Action</DialogTitle>
          <DialogContent>
            <Typography>{confirmMessage}</Typography>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setConfirmOpen(false)} color="secondary">
              Cancel
            </Button>
            <Button
              onClick={() => {
                confirmAction?.();
                setConfirmOpen(false);
              }}
              color="primary"
            >
              Confirm
            </Button>
          </DialogActions>
        </Dialog>
      </Box>
    </Box>
  );
};

export default AdminVotersProfileMgt;