import React, { useState, useEffect, useRef } from "react";
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  useMediaQuery,
  useTheme,
  Slide,
  Chip,
  Stack,
  Avatar,
} from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import EncodingSidebar from "../../components/EncodingSidebar";
import io from "socket.io-client";
import AddNewPayoutDialog from "../admin/dialogs/AddNewPayoutDialog";

// Slide transition for smooth dialog opening
const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const SERVER_URL = "http://192.168.0.149:4000";;

const AdminPayoutManagement = () => {
  const [payouts, setPayouts] = useState([]);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [connectionStatus, setConnectionStatus] = useState("Connecting...");
  const [heartbeatOn, setHeartbeatOn] = useState(false);
  const socketRef = useRef(null);

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  // Heartbeat blink effect
  useEffect(() => {
    if (connectionStatus === "Connected") {
      const interval = setInterval(() => setHeartbeatOn((prev) => !prev), 500);
      return () => clearInterval(interval);
    } else {
      setHeartbeatOn(false);
    }
  }, [connectionStatus]);

  useEffect(() => {
    socketRef.current = io(SERVER_URL, {
      reconnectionAttempts: 5,
      transports: ["websocket"],
    });

    // Socket connection events
    socketRef.current.on("connect", () => setConnectionStatus("Connected"));
    socketRef.current.on("disconnect", () => setConnectionStatus("Disconnected"));
    socketRef.current.on("reconnect_attempt", () => setConnectionStatus("Reconnecting..."));
    socketRef.current.on("reconnect_failed", () => setConnectionStatus("Failed to reconnect"));

    // Initial fetch
    fetch(`${SERVER_URL}/getPayouts`)
      .then((res) => res.json())
      .then((data) => setPayouts(data))
      .catch(() => setConnectionStatus("Failed to fetch data"));

    // Socket updates
    socketRef.current.on("newPayoutAdded", (payout) => {
      setPayouts((prev) => {
        if (prev.some((p) => p.fileName === payout.fileName)) return prev;
        return [...prev, payout];
      });
    });

    socketRef.current.on("allPayouts", (data) => {
      // Accept both old object shape (fileName -> fileData) and new lightweight array of metadata
      if (Array.isArray(data)) {
        // data is an array of metadata objects: { fileName, title, venue, amount, beneficiaryCount, category, sector, date, rowCount }
        const arr = data.map((d) => ({
          fileName: d.fileName || d.name || "",
          title: d.title || "",
          venue: d.venue || "",
          amount: d.amount || "",
          beneficiaryCount: d.beneficiaryCount || "",
          category: d.category || "",
          sector: d.sector || "",
          date: d.date || "",
          data: [], // don't populate full rows here — client should fetch when needed
          _rowCount: d.rowCount || 0,
        }));
        setPayouts(arr);
      } else if (data && typeof data === "object") {
        // backwards-compatible: server sent full importedFiles object
        const arr = Object.keys(data).map((fileName) => {
          const fileData = data[fileName];
          return {
            fileName,
            title: fileData._meta?.title || "",
            venue: fileData._meta?.venue || "",
            amount: fileData._meta?.amount || "",
            beneficiaryCount: fileData._meta?.beneficiaryCount || "",
            category: fileData._meta?.category || "",
            sector: fileData._meta?.sector || "",
            date: fileData._meta?.date || "",
            data: fileData.rows || [],
          };
        });
        setPayouts(arr);
      }
    });

    socketRef.current.on("payoutUpdated", ({ fileName, rowIndex, newRow }) => {
      setPayouts((prev) =>
        prev.map((p) =>
          p.fileName === fileName
            ? { ...p, data: (p.data || []).map((row, i) => (i === rowIndex ? newRow : row)) }
            : p
        )
      );
    });

    return () => socketRef.current.disconnect();
  }, []);

  const handleAddPayout = async (formData) => {
  try {
    const res = await fetch(`${SERVER_URL}/uploadPayout`, {
      method: "POST",
      body: formData,
    });

    // Try to parse the JSON response
    const data = await res.json();

    if (!res.ok) {
      // If the server returns an error field, use it
      const errorMsg = data?.error || "Upload failed";
      throw new Error(errorMsg);
    }

    // Return parsed data to allow further handling
    return data;
  } catch (err) {
    console.error("Upload error:", err);
    // Rethrow so caller can catch it
    throw new Error(err.message || "Failed to upload payout");
  }
};

  const handleDeleteClick = (fileName) => {
    setSelectedFile(fileName);
    setConfirmOpen(true);
  };

  const handleConfirmDelete = async () => {
    try {
      await fetch(`${SERVER_URL}/deletePayout`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ fileName: selectedFile }),
      });
      setPayouts((prev) => prev.filter((p) => p.fileName !== selectedFile));
    } catch (err) {
      console.error(err);
      alert("Failed to delete payout");
    } finally {
      setConfirmOpen(false);
      setSelectedFile(null);
    }
  };

  const handleCancelDelete = () => {
    setConfirmOpen(false);
    setSelectedFile(null);
  };

  // Connection status color
  const getStatusColor = (status) => {
    switch (status) {
      case "Connected":
        return "success";
      case "Disconnected":
      case "Failed to reconnect":
        return "error";
      case "Reconnecting...":
      case "Connecting...":
        return "warning";
      default:
        return "default";
    }
  };

  return (
    <Box display={{ xs: "block", md: "flex" }}>
      <EncodingSidebar />
      <Box flex={1} p={{ xs: 2, md: 3 }}>
        <Stack direction="row" justifyContent="space-between" alignItems="center" mb={2}>
          <Typography variant="h4">Admin Payout Management</Typography>
          <Stack direction="row" alignItems="center" spacing={1}>
            {connectionStatus === "Connected" && (
              <Avatar
                sx={{
                  width: 12,
                  height: 12,
                  bgcolor: heartbeatOn ? "success.main" : "grey.300",
                }}
              />
            )}
            <Chip label={connectionStatus} color={getStatusColor(connectionStatus)} />
          </Stack>
        </Stack>

        <Button
          variant="contained"
          color="primary"
          onClick={() => setDialogOpen(true)}
          sx={{ mb: 2 }}
        >
          Add New Payout
        </Button>

        {payouts.length > 0 && (
          <Paper sx={{ p: { xs: 2, md: 3 }, mt: 2, overflowX: "auto" }}>
            <Typography variant="h6" mb={2}>
              Payout Schedules
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Title</TableCell>
                    <TableCell>Venue</TableCell>
                    <TableCell>Amount</TableCell>
                    <TableCell>Beneficiaries</TableCell>
                    <TableCell>Category</TableCell>
                    <TableCell>Sector</TableCell>
                    <TableCell>Date</TableCell>
                    <TableCell>File</TableCell>
                    <TableCell>Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {payouts.map((p) => (
                    <TableRow key={p.fileName} hover>
                      <TableCell>{p.title}</TableCell>
                      <TableCell>{p.venue}</TableCell>
                      <TableCell>₱{p.amount}</TableCell>
                      <TableCell>{p.beneficiaryCount}</TableCell>
                      <TableCell>{p.category}</TableCell>
                      <TableCell>{p.sector}</TableCell>
                      <TableCell>{p.date}</TableCell>
                      <TableCell>{p.fileName}</TableCell>
                      <TableCell>
                        <IconButton color="error" onClick={() => handleDeleteClick(p.fileName)}>
                          <DeleteIcon />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        )}

        <AddNewPayoutDialog
          open={dialogOpen}
          onClose={() => setDialogOpen(false)}
          onSubmit={handleAddPayout}
        />

        <Dialog
          open={confirmOpen}
          onClose={handleCancelDelete}
          fullScreen={isMobile}
          TransitionComponent={Transition}
        >
          <DialogTitle>Confirm Delete</DialogTitle>
          <DialogContent>
            Are you sure you want to delete <strong>{selectedFile}</strong>?
          </DialogContent>
          <DialogActions>
            <Button onClick={handleCancelDelete}>Cancel</Button>
            <Button color="error" variant="contained" onClick={handleConfirmDelete}>
              Delete
            </Button>
          </DialogActions>
        </Dialog>
      </Box>
    </Box>
  );
};

export default AdminPayoutManagement;