import React, { useState } from "react";
import { auth, db } from "../firebase";
import { signInWithEmailAndPassword } from "firebase/auth";
import { doc, getDoc } from "firebase/firestore";
import { useNavigate } from "react-router-dom";
import { usersDB, seedDefaultUsers } from "../db/usersDB";
import {
  Box,
  Button,
  TextField,
  Typography,
  Paper,
  CircularProgress,
  Alert,
} from "@mui/material";
import PersonIcon from "@mui/icons-material/Person";
import EmailIcon from "@mui/icons-material/Email";
import LockIcon from "@mui/icons-material/Lock";
import { InputAdornment, IconButton } from "@mui/material";
import SecurityIcon from "@mui/icons-material/Security";

const Login = () => {
  const navigate = useNavigate();
  const [isEncodingSection, setIsEncodingSection] = useState(false);
  const [emailOrUsername, setEmailOrUsername] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [showPassword, setShowPassword] = useState(false);

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    await seedDefaultUsers();

    if (isEncodingSection) {
      // OFFLINE LOGIN USING INDEXEDDB
      setTimeout(async () => {
        try {
          const user = await usersDB.users
            .where("username")
            .equals(emailOrUsername)
            .and((u) => u.password === password)
            .first();

          if (user) {
            // Save session locally
            localStorage.setItem("uid", `offline-${user.username}`);
            localStorage.setItem("username", user.username); // ✅ important
            localStorage.setItem("role", user.role);
            localStorage.setItem("name", user.name);

            setLoading(false);

            // Redirect by role
            if (user.role === "admin") {
              navigate("/encoding/admin", { replace: true });
            } else {
              navigate("/encoder/encoding", { replace: true });
            }
          } else {
            setError("Invalid username or password.");
            setLoading(false);
          }
        } catch (err) {
          console.error("Offline login error:", err);
          setError("Login failed due to internal error.");
          setLoading(false);
        }
      }, 500);
    } else {
      // FIREBASE LOGIN
      try {
        const { user } = await signInWithEmailAndPassword(auth, emailOrUsername, password);

        const userDoc = await getDoc(doc(db, "users", user.uid));
        if (!userDoc.exists()) {
          setError("User profile not found.");
          setLoading(false);
          return;
        }

        const { role, name } = userDoc.data();
        localStorage.setItem("uid", user.uid);
        localStorage.setItem("username", emailOrUsername); // ✅ store for sidebar
        localStorage.setItem("role", role);
        localStorage.setItem("name", name || "");

        setLoading(false);

        if (role === "admin") {
          navigate("/admin", { replace: true });
        } else {
          alert(`Welcome back, ${name || "User"}!`);
        }
      } catch (err) {
        console.error("Login failed:", err);
        setError("Invalid email or password.");
        setLoading(false);
      }
    }
  };

  return (
    <Box
      sx={{
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        bgcolor: "#f5f8fc",
      }}
    >
      <Paper
        elevation={10}
        sx={{
          p: 5,
          width: 380,
          borderRadius: 4,
          bgcolor: "rgba(255,255,255,0.9)",
          backdropFilter: "blur(20px)",
          textAlign: "center",
          boxShadow: "0 8px 24px rgba(0,0,0,0.1)",
        }}
      >
        <SecurityIcon sx={{ fontSize: 60, color: "#1f8ef1", mb: 1 }} />
        <Typography variant="h5" sx={{ mb: 0.5, color: "#1f8ef1", fontWeight: 700, letterSpacing: 1.5 }}>
          MRTU SYSTEM
        </Typography>
        <Typography variant="subtitle1" sx={{ mb: 3, color: "#555" }}>
          Secure Admin Login
        </Typography>

        <Button
          variant="outlined"
          size="small"
          sx={{ mb: 2 }}
          onClick={() => setIsEncodingSection((prev) => !prev)}
        >
          {isEncodingSection ? "Switch to Online Login" : "Switch to Encoding Section"}
        </Button>

        {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

        <Box component="form" onSubmit={handleLogin}>
         <TextField
            label={isEncodingSection ? "Username" : "Email"}
            variant="outlined"
            fullWidth
            margin="normal"
            value={emailOrUsername}
            onChange={(e) => setEmailOrUsername(e.target.value)}
            required
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  {isEncodingSection ? (
                    <PersonIcon sx={{ color: "#1f8ef1" }} />
                  ) : (
                    <EmailIcon sx={{ color: "#1f8ef1" }} />
                  )}
                </InputAdornment>
              ),
            }}
          />

         <TextField
            label="Password"
            variant="outlined"
            fullWidth
            type={showPassword ? "text" : "password"}
            margin="normal"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <LockIcon sx={{ color: "#1f8ef1" }} />
                </InputAdornment>
              ),
              endAdornment: (
                <InputAdornment position="end">
                  <IconButton onClick={() => setShowPassword((prev) => !prev)} edge="end">
                    
                  </IconButton>
                </InputAdornment>
              ),
            }}
          />

          <Button
            type="submit"
            variant="contained"
            fullWidth
            disabled={loading}
            sx={{
              mt: 3,
              py: 1.2,
              fontWeight: "bold",
              fontSize: "1rem",
              bgcolor: "#1f8ef1",
              "&:hover": { bgcolor: "#0f75d1" },
            }}
          >
            {loading ? (
              <>
                <CircularProgress size={20} sx={{ color: "#fff", mr: 1 }} /> Authenticating...
              </>
            ) : (
              "LOGIN"
            )}
          </Button>

          <Typography
          variant="caption"
          sx={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            mt: 2,
            color: "#777",
            fontSize: "0.75rem",
          }}
        >
          <LockIcon sx={{ fontSize: 16, mr: 0.5, color: "#1f8ef1" }} />
          Your credentials are encrypted and protected.
        </Typography>
        </Box>
      </Paper>
    </Box>
  );
};

export default Login;